// Replays proto/testdata/tools_vectors.json (generated by
// proto/go/tools/payer_vectors_test.go) against proto/ts/src/tools, then pins
// the consumer-side sanitizing, which has no Go twin.

import { describe, it, expect } from 'vitest'
import * as fs from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'
import { hex } from '@scure/base'

import * as tools from '../src/tools/index.js'
import {
    chatCachedTokens,
    chatGeneratedOutputTokens,
    chatReasoningTokens,
    generatedOutputTokens,
    iconDataUrl,
    iconHostKey,
    iconMimeFromBytes,
    isLinkableUrl,
    MAX_ACTION_QUERY_BYTES,
    MAX_ACTION_SOURCES,
    MAX_ACTION_URL_BYTES,
    MAX_ICON_HOSTS,
    MAX_ICON_RAW_BYTES,
    MAX_ICONS_TOTAL_B64_BYTES,
    parseStatusEvent,
    parseToolAction,
    partialImageDataUrl,
    responsesCachedTokens,
    responsesGeneratedOutputTokens,
    responsesReasoningTokens,
    sanitizeIcons,
    STATUS_EVENT_IMAGE_COMPLETED,
    STATUS_EVENT_IMAGE_PARTIAL,
    STATUS_EVENT_IMAGE_PROGRESS,
    STATUS_EVENT_TOOL_CALL_COMPLETED,
} from '../src/tools/index.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(
    fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'tools_vectors.json'), 'utf8'),
) as Json

// Plain-object form, so a null-prototype icons map compares by content.
const plain = (x: unknown): unknown => JSON.parse(JSON.stringify(x))

describe('tools_vectors.json', () => {
    it('is the schema this test expects', () => {
        expect(v.version).toBe(1)
        for (const k of ['frames', 'linkable_urls', 'icon_host_keys', 'icon_mimes', 'generated_output_tokens', 'usage']) {
            expect(v[k].length).toBeGreaterThan(0)
        }
    })

    describe('constants', () => {
        for (const [name, want] of Object.entries(v.constants as Record<string, unknown>)) {
            it(name, () => {
                expect((tools as Record<string, unknown>)[name]).toBe(want)
            })
        }
    })

    // A node's own frames must come back whole: a dropped field here is one a
    // payer would silently never see.
    describe('frames as a node emits them parse back unchanged', () => {
        for (const c of v.frames) {
            it(c.name, () => {
                expect(plain(parseStatusEvent(c.frame))).toStrictEqual(c.frame)
            })
        }
    })

    // The node keys each icon by its source's host; if the two sides derived
    // the key differently, every icon would miss its lookup.
    it('every icon a node sends is keyed by one of its sources', () => {
        let checked = 0
        for (const c of v.frames) {
            const a = c.frame.action
            if (a?.icons === undefined) continue
            const hosts = a.sources.map((s: Json) => iconHostKey(s.url))
            for (const key of Object.keys(a.icons)) {
                expect(hosts).toContain(key)
                checked++
            }
        }
        expect(checked).toBeGreaterThan(0)
    })

    // A URL Go accepts but the WHATWG parser refuses can't be opened by a
    // browser, so the TS port refuses it too.
    describe('isLinkableUrl', () => {
        for (const c of v.linkable_urls) {
            it(JSON.stringify(c.url), () => {
                expect(isLinkableUrl(c.url)).toBe(c.ok && !c.whatwg_refuses)
            })
        }
    })

    describe('iconHostKey', () => {
        for (const c of v.icon_host_keys) {
            it(JSON.stringify(c.url), () => {
                expect(iconHostKey(c.url)).toBe(c.ok && !c.whatwg_refuses ? c.want : null)
            })
        }
    })

    describe('iconMimeFromBytes', () => {
        for (const c of v.icon_mimes) {
            it(c.bytes_hex || '(empty)', () => {
                expect(iconMimeFromBytes(hex.decode(c.bytes_hex))).toBe(c.want)
            })
        }
    })

    describe('generatedOutputTokens', () => {
        for (const c of v.generated_output_tokens) {
            it(`(${c.prompt}, ${c.completion}, ${c.reasoning}, ${c.total})`, () => {
                const args = [c.prompt, c.completion, c.reasoning, c.total].map(Number) as [number, number, number, number]
                expect(String(generatedOutputTokens(...args))).toBe(c.want)
            })
        }
    })

    describe('usage', () => {
        for (const c of v.usage) {
            it(c.name, () => {
                const got =
                    c.kind === 'chat'
                        ? [chatCachedTokens(c.usage), chatReasoningTokens(c.usage), chatGeneratedOutputTokens(c.usage)]
                        : [
                              responsesCachedTokens(c.usage),
                              responsesReasoningTokens(c.usage),
                              responsesGeneratedOutputTokens(c.usage),
                          ]
                expect(got.map(String)).toEqual([c.cached_tokens, c.reasoning_tokens, c.generated_output_tokens])
            })
        }
    })
})

// The node applies these rules before it emits; a consumer can't assume the
// node it reached did, so the parser applies them again.
describe('consumer-side sanitizing (TS only)', () => {
    const PNG_MAGIC = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]
    // n bytes that sniff as PNG, base64-encoded.
    const png = (n: number) => {
        const b = new Uint8Array(n)
        b.set(PNG_MAGIC.slice(0, n))
        return Buffer.from(b).toString('base64')
    }
    const pngIcon = (n = 10) => ({ mime: 'image/png', data_b64: png(n) })
    const status = (extra: Json = {}): Json => ({
        type: STATUS_EVENT_TOOL_CALL_COMPLETED,
        item_id: 'zstc_1',
        output_index: 0,
        tool: 'zs_web_search',
        ...extra,
    })
    const search = (extra: Json = {}): Json => ({ type: 'search', query: 'q', ...extra })

    it('ignores unknown types and refuses frames missing what they need', () => {
        expect(parseStatusEvent({ type: 'response.output_text.delta', item_id: 'x' })).toBeNull()
        expect(parseStatusEvent(status({ item_id: '' }))).toBeNull()
        expect(parseStatusEvent(status({ tool: undefined }))).toBeNull()
        expect(parseStatusEvent(status({ output_index: -1 }))).toBeNull()
        expect(parseStatusEvent({ type: STATUS_EVENT_IMAGE_PROGRESS, item_id: 'x', value: 1 })).toBeNull()
        expect(parseStatusEvent({ type: STATUS_EVENT_IMAGE_COMPLETED, item_id: 'x', response: '{}' })).toBeNull()
        expect(parseStatusEvent([status()])).toBeNull()
    })

    // value/max is a fraction a renderer divides by.
    it('refuses image progress with a zero max', () => {
        const p = { type: STATUS_EVENT_IMAGE_PROGRESS, item_id: 'x', value: 0 }
        expect(parseStatusEvent({ ...p, max: 0 })).toBeNull()
        expect(parseStatusEvent({ ...p, max: 1 })).toStrictEqual({ ...p, max: 1 })
    })

    it('keeps the frame and drops a malformed action', () => {
        expect(parseStatusEvent(status({ action: 'search' }))).toStrictEqual(status())
        expect(parseStatusEvent(status({ action: { query: 'x' } }))).toStrictEqual(status())
    })

    it('accepts only the action types a node emits, and only with something to show', () => {
        expect(parseToolAction({ type: 'find_in_page', query: 'x' })).toBeNull()
        expect(parseToolAction({ type: 'search' })).toBeNull()
        expect(parseToolAction({ type: 'search', query: '   ' })).toBeNull()
        expect(parseToolAction({ type: 'open_page' })).toBeNull()
        expect(parseToolAction({ type: 'open_page', url: 'javascript:alert(1)' })).toBeNull()
        expect(parseToolAction({ type: 'search', icons: { 'a.com': pngIcon() } })).toBeNull()
    })

    // A search never carries a URL and a page read never carries a query; one
    // that does is not an action a node built.
    it('keeps query only on a search and url only on an open_page', () => {
        expect(parseToolAction({ type: 'search', query: 'q', url: 'https://a.com/' })).toStrictEqual({
            type: 'search',
            query: 'q',
        })
        expect(parseToolAction({ type: 'open_page', query: 'q', url: 'https://a.com/' })).toStrictEqual({
            type: 'open_page',
            url: 'https://a.com/',
        })
    })

    // Consumers render these as links: a javascript: URL must never reach an href.
    it('drops URLs that are not http(s), not exactly as fetched, or longer than the bound', () => {
        const url = (n: number) => {
            const head = 'https://example.com/'
            return head + 'a'.repeat(n - head.length)
        }
        expect(parseToolAction({ type: 'open_page', url: url(MAX_ACTION_URL_BYTES) })?.url).toBe(url(MAX_ACTION_URL_BYTES))
        expect(parseToolAction({ type: 'open_page', url: url(MAX_ACTION_URL_BYTES + 1) })).toBeNull()
        expect(parseToolAction({ type: 'open_page', url: ' https://a.com/' })).toBeNull()
        expect(parseToolAction({ type: 'open_page', url: 'https://a.com\\@evil.com/' })).toBeNull()
        const got = parseToolAction(
            search({
                sources: [
                    { type: 'url', url: 'data:text/html,x' },
                    { type: 'url', url: 'https://a.com/' },
                    { type: 'url', url: 'https://a.com/' },
                    { type: 'file', url: 'https://b.com/' },
                    'https://c.com/',
                ],
            }),
        )
        expect(got).toStrictEqual(search({ sources: [{ type: 'url', url: 'https://a.com/' }] }))
    })

    it('caps sources, and clips an over-long query without splitting a character', () => {
        const sources = Array.from({ length: MAX_ACTION_SOURCES + 5 }, (_, i) => ({ type: 'url', url: `https://s${i}.com/` }))
        expect(parseToolAction(search({ sources }))?.sources).toHaveLength(MAX_ACTION_SOURCES)
        const q = 'é'.repeat(MAX_ACTION_QUERY_BYTES / 2)
        expect(parseToolAction(search({ query: q }))?.query).toBe(q)
        expect(parseToolAction(search({ query: `x${q}` }))?.query).toBe(`x${q.slice(1)}`)
        expect(parseToolAction(search({ query: `  ${q}  ` }))?.query).toBe(q)
    })

    // A node fetches icons for its sources' hosts and nothing else.
    it('keeps an icon only for a host among the action sources', () => {
        const got = parseToolAction(
            search({
                sources: [{ type: 'url', url: 'https://www.a.com/x' }],
                icons: { 'www.a.com': pngIcon(), 'b.com': pngIcon() },
            }),
        )
        expect(plain(got?.icons)).toStrictEqual({ 'www.a.com': pngIcon() })
        expect(parseToolAction(search({ sources: [{ type: 'url', url: 'https://a.com/' }], icons: { 'b.com': pngIcon() } })))
            .toStrictEqual(search({ sources: [{ type: 'url', url: 'https://a.com/' }] }))
    })

    it('admits only allowlisted raster icons whose bytes match their mime, within the per-icon bound', () => {
        const ok = pngIcon()
        const got = sanitizeIcons({
            'a.com': ok,
            'svg.com': { mime: 'image/svg+xml', data_b64: png(10) },
            'bad.com': { mime: 'image/png', data_b64: 'not base64!' },
            'unpadded.com': { mime: 'image/png', data_b64: 'iVBORw' },
            'lies.com': { mime: 'image/gif', data_b64: png(10) },
            'big.com': pngIcon(MAX_ICON_RAW_BYTES + 1),
            'edge.com': pngIcon(MAX_ICON_RAW_BYTES),
            'Upper.com': ok,
            'a.com:443': ok,
            'xn--mnchen-3ya.de': ok,
            '[::ffff:1.2.3.4]': ok,
            '[::ffff:102:304]': ok,
        })
        expect(plain(got)).toStrictEqual({
            'a.com': ok,
            'edge.com': pngIcon(MAX_ICON_RAW_BYTES),
            'xn--mnchen-3ya.de': ok,
            '[::ffff:102:304]': ok,
        })
        expect(sanitizeIcons({ 'a.com': { mime: 'image/svg+xml', data_b64: png(10) } })).toBeNull()
    })

    // An icons map is keyed by whatever a node chose to send.
    it('treats a hostile key as data, and bounds key length', () => {
        const got = sanitizeIcons(JSON.parse(`{"__proto__": ${JSON.stringify(pngIcon())}, "a.com": ${JSON.stringify(pngIcon())}}`))
        expect(got).not.toBeNull()
        expect(Object.getPrototypeOf(got)).toBeNull()
        expect(Object.keys(got!)).toEqual(['__proto__', 'a.com'])
        expect(got!['__proto__']).toStrictEqual(pngIcon())
        expect(({} as Json).mime).toBeUndefined()

        const label = 'a'.repeat(63)
        const host253 = [label, label, label, 'a'.repeat(61)].join('.')
        expect(host253).toHaveLength(253)
        expect(Object.keys(sanitizeIcons({ [host253]: pngIcon() }) ?? {})).toEqual([host253])
        expect(sanitizeIcons({ [`${host253}a`]: pngIcon() })).toBeNull()
    })

    // The host cap is a prefix; the byte budget is first-fit, so one large icon
    // near the head doesn't blank every chip after it.
    it('caps hosts as a prefix and fits the byte budget first-fit', () => {
        const many = Object.fromEntries(Array.from({ length: MAX_ICON_HOSTS + 3 }, (_, i) => [`h${i}.com`, pngIcon(8)]))
        expect(Object.keys(sanitizeIcons(many) ?? {})).toEqual(Object.keys(many).slice(0, MAX_ICON_HOSTS))

        const big = pngIcon(MAX_ICON_RAW_BYTES)
        const fit = Math.floor(MAX_ICONS_TOTAL_B64_BYTES / big.data_b64.length)
        const icons: Json = {}
        for (let i = 0; i < fit; i++) icons[`big${i}.com`] = big
        icons['over.com'] = big
        icons['small.com'] = pngIcon(8)
        const got = Object.keys(sanitizeIcons(icons) ?? {})
        expect(got).not.toContain('over.com')
        expect(got).toContain('small.com')
        expect(got).toHaveLength(fit + 1)
    })

    it('builds a data URL only from an icon a node may send', () => {
        expect(iconDataUrl({ mime: 'image/png', data_b64: 'iVBORw0KGgo=' })).toBe('data:image/png;base64,iVBORw0KGgo=')
        expect(iconDataUrl({ mime: 'image/x-icon', data_b64: 'AAABAA==' })).toBe('data:image/x-icon;base64,AAABAA==')
        expect(iconDataUrl({ mime: 'image/png', data_b64: 'AAAA' })).toBeNull()
        expect(iconDataUrl({ mime: 'image/svg+xml', data_b64: 'iVBORw0KGgo=' })).toBeNull()
        expect(iconDataUrl({ mime: 'image/png', data_b64: 'AA,"><script>' })).toBeNull()
        expect(iconDataUrl({ mime: 'image/png', data_b64: '' })).toBeNull()
        expect(iconDataUrl(null)).toBeNull()
        expect(iconDataUrl(undefined)).toBeNull()
    })

    it('keeps a preview render only as valid base64, with a mime a preview comes in', () => {
        const p = { type: STATUS_EVENT_IMAGE_PARTIAL, item_id: 'x' }
        expect(parseStatusEvent({ ...p, partial_image_b64: 'not base64!' })).toBeNull()
        expect(parseStatusEvent({ ...p, partial_image_b64: 'iVBORw' })).toBeNull()
        expect(parseStatusEvent({ ...p, partial_image_b64: 'iVBORw0KGgo=', mime: 'image/svg+xml' })).toStrictEqual({
            ...p,
            partial_image_b64: 'iVBORw0KGgo=',
        })
        expect(parseStatusEvent({ ...p, partial_image_b64: 'UklGRgAAAABXRUJQ', mime: 'image/webp' })).toStrictEqual({
            ...p,
            partial_image_b64: 'UklGRgAAAABXRUJQ',
            mime: 'image/webp',
        })
    })

    // The bytes decide the data: URL's type, not the label beside them.
    it('types a preview data URL by its bytes', () => {
        expect(partialImageDataUrl({ partial_image_b64: 'iVBORw0KGgo=' })).toBe('data:image/png;base64,iVBORw0KGgo=')
        expect(partialImageDataUrl({ partial_image_b64: '/9j/4AAQ' })).toBe('data:image/jpeg;base64,/9j/4AAQ')
        expect(partialImageDataUrl({ partial_image_b64: 'UklGRgAAAABXRUJQ' })).toBe('data:image/webp;base64,UklGRgAAAABXRUJQ')
        expect(partialImageDataUrl({ partial_image_b64: 'R0lGODlhAQABAAAAACw=' })).toBeNull()
        expect(partialImageDataUrl({ partial_image_b64: 'PHN2Zz4=' })).toBeNull()
        expect(partialImageDataUrl({ partial_image_b64: 'not base64!' })).toBeNull()
    })

    it('reads a malformed or absent usage count as 0, as Go decodes it', () => {
        expect(chatGeneratedOutputTokens({ prompt_tokens: 10, completion_tokens: '5' as unknown as number })).toBe(0)
        expect(responsesCachedTokens({})).toBe(0)
        expect(chatCachedTokens({ prompt_tokens_details: {}, prompt_cache_hit_tokens: 6 })).toBe(0)
    })

    it('reads a negative or fractional argument as 0', () => {
        expect(generatedOutputTokens(10, 5, 3, 18)).toBe(8)
        expect(generatedOutputTokens(10, -5, 3, 18)).toBe(3)
        expect(generatedOutputTokens(10, 5.5, 3, 18)).toBe(3)
        expect(generatedOutputTokens(10, 5, -3, 18)).toBe(5)
        expect(generatedOutputTokens(10, 5, 3, 18.5)).toBe(5)
        expect(generatedOutputTokens(-10, 5, 3, 8)).toBe(8)
        expect(generatedOutputTokens(Number.NaN, 5, 3, 8)).toBe(8)
    })

    it('leaves completion alone where the sum would pass 2^53', () => {
        const big = Number.MAX_SAFE_INTEGER - 5
        expect(generatedOutputTokens(0, big, 10, Number.MAX_SAFE_INTEGER)).toBe(big)
    })
})
